import{_ as t}from"./chunks/7.DkEsj_3r.js";import{_ as e}from"./chunks/4.4-zpfiltr.CDulehK1.js";import{_ as a,o as r,c as s,aa as i}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/academy/img/vystupy-spp/01.webp",y=JSON.parse('{"title":"Výstupy soupisů","description":"","frontmatter":{"title":"Výstupy soupisů","wiki":"cs:performedworks:output_methods"},"headers":[],"relativePath":"performedworks/output_methods.md","filePath":"performedworks/output_methods.md","lastUpdated":1794209661000}'),p={name:"performedworks/output_methods.md"};function n(d,o,u,v,k,h){return r(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="vystupy-soupisu" tabindex="-1">Výstupy soupisů <a class="header-anchor" href="#vystupy-soupisu" aria-label="Permalink to &quot;Výstupy soupisů&quot;">​</a></h1><p>Výstupem soupisu je zjišťovací protokol za období, odsouhlasený mezi stavebníkem a zhotovitelem nebo mezi zhotovitelem a podzhotovitelem. Stáhnete ho do Excelu nebo PDF, schválený protokol v PDF slouží jako podklad a příloha k faktuře.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/vystupy-spp">Vytisknout nebo exportovat soupis</a> v Akademii.</p><h2 id="zjistovaci-protokol" tabindex="-1">Zjišťovací protokol <a class="header-anchor" href="#zjistovaci-protokol" aria-label="Permalink to &quot;Zjišťovací protokol&quot;">​</a></h2><p>Zjišťovací protokol dokumentuje soupis jedné dvojice firem za jedno období. Na stavbě s mnoha podzhotoviteli jich tak za jedno období vzniknou i desítky – viz <a href="/buildary-help-preview/performedworks/#zakladni-pojmy">Soupisy provedených prací</a>.</p><p>Protokoly vybrané dvojice firem zobrazíte tlačítkem <strong>Protokoly</strong> v záhlaví <a href="/buildary-help-preview/performedworks/application_window">okna soupisu</a>.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Okno SPP Zhotovitele se schváleným protokolem, tlačítkem Protokoly v záhlaví a menu Tisky a exporty vpravo nad tabulkou" loading="lazy"></figure><h2 id="tisky-a-exporty" tabindex="-1">Tisky a exporty <a class="header-anchor" href="#tisky-a-exporty" aria-label="Permalink to &quot;Tisky a exporty&quot;">​</a></h2><p>Menu <strong>Tisky a exporty</strong> v okně soupisu stáhne zjišťovací protokol období vybraného v záhlaví.</p><p>Export je ve dvou formátech:</p><ul><li>Excel – sešit se dvěma listy: <strong>Rekap. za stavbu a po objektech</strong> a <strong>Položkový výpis</strong>.</li><li>PDF – zjišťovací protokol jako dokument.</li></ul><p>Export můžete stáhnout i ve variantě <strong>Pouze nenulové položky</strong>, která obsahuje jen položky, na kterých bylo provedeno čerpání.</p><p>Do exportu se dostanou jen položky, které odpovídají zapnutému filtru – například jen položky vybraných čísel smluv. Filtry popisuje <a href="/buildary-help-preview/performedworks/application_window#filtrace">Okno soupisu</a>.</p><h2 id="co-protokol-obsahuje" tabindex="-1">Co protokol obsahuje <a class="header-anchor" href="#co-protokol-obsahuje" aria-label="Permalink to &quot;Co protokol obsahuje&quot;">​</a></h2><ul><li><strong>Záhlaví</strong> – stavba, období, stav období, čísla stavby, údaje o zhotoviteli a objednateli (název, sídlo, IČO) a cena z rozpočtu.</li><li><strong>Souhrn</strong> za stavbu a po stavebních objektech.</li><li><strong>Položkový výpis</strong> – položky rozpočtu se stejnými úrovněmi jako v okně soupisu.</li><li><strong>Kdo a kdy soupis schválil.</strong></li><li><strong>Měna</strong> – podle pole <strong>Měna</strong> v Nastavení stavby, viz <a href="/buildary-help-preview/diary/projectsetup#udaje-o-stavbe">Založit stavbu</a>.</li></ul><p>Částky jsou rozdělené do sloupců:</p><table tabindex="0"><thead><tr><th>Sloupec</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Celkem</strong></td><td>Množství, jednotková cena a cena podle rozpočtu.</td></tr><tr><td><strong>Předchozí období</strong></td><td>Čerpání ve všech dřívějších obdobích.</td></tr><tr><td><strong>Aktuální období</strong></td><td>Čerpání ve vybraném období.</td></tr><tr><td><strong>Předch. + Akt. období</strong></td><td>Čerpání celkem včetně vybraného období.</td></tr><tr><td><strong>Zbývá</strong></td><td>Co z rozpočtu zbývá vyčerpat.</td></tr></tbody></table><div class="gallery"><figure class="shot"><img src="'+t+'" alt="Zjišťovací protokol v PDF se základními informacemi, stavem období Ve schvalování, údaji o zhotoviteli a objednateli a souhrnem po objektech" loading="lazy"><figcaption>Souhrn v PDF</figcaption></figure><figure class="shot"><img src="'+e+'" alt="Položkový výpis soupisu v Excelu se stavem období Schváleno, sloupci Celkem, Předchozí období, Aktuální období a Zbývá a listy Rekap. za stavbu a po objektech a Položkový výpis" loading="lazy"><figcaption>Položkový výpis v Excelu</figcaption></figure></div><h2 id="podklad-k-fakturaci" tabindex="-1">Podklad k fakturaci <a class="header-anchor" href="#podklad-k-fakturaci" aria-label="Permalink to &quot;Podklad k fakturaci&quot;">​</a></h2><p>V záhlaví výstupu je u <strong>Stav období</strong> uvedeno, zda smíte dokument použít k fakturaci:</p><table tabindex="0"><thead><tr><th>Stav období ve výstupu</th><th>Použití</th></tr></thead><tbody><tr><td><strong>Ve schvalování</strong></td><td>Protokol ještě není schválený. Nelze ho použít jako podklad k fakturaci.</td></tr><tr><td><strong>Schváleno</strong></td><td>Protokol je ve stavu <strong>Uzavřeno</strong>. Použijte ho jako podklad a přílohu k fakturaci.</td></tr></tbody></table><p>Když stavebník protokol schválí, dostane zhotovitel e-mail se zjišťovacím protokolem v PDF. Protokol je vygenerovaný automaticky a elektronicky podepsaný, podpis ho chrání proti změnám. Přiložte ho k faktuře v elektronické nebo vytištěné podobě. U soupisu podzhotovitele dostane protokol podzhotovitel, když ho schválí zhotovitel.</p><p>PDF obsahuje také metadata, která můžete využít při příjmu a schvalování faktury ve svém ERP systému. Podrobnosti vám sdělí konzultanti Buildary na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p>',23)])])}const g=a(p,[["render",n]]);export{y as __pageData,g as default};
